	('e4140bf0-38c8-4c05-8618-54cb1ce659c0', '{player-1} er lei av å snike seg bak ryggen på {player-2} med {player-0} og avslører forholdet! {player-2} sklir inn i en tung depresjon mens elskerne fortsetter affæren. {player-2}, ta 5 depresive slurker.', '2023-04-09 19:42:00+00', '2024-12-05 23:15:20.782599+00', '9043927d-8a57-4e04-afb8-c6ae9918cfc2', true, 'Skitur! ⛷️', NULL),
