	('0ac66f27-4fca-464a-b8b6-4f399095caf9', 'Stresset over å holde utroskapen hemmelig tar på for {player-0} og {player-1}. De melder seg derfor inn i Hverdagsalkoholiker-foreningen. Ta 4 slurker hver.', '2023-04-09 19:42:00+00', '2024-12-05 23:15:20.794407+00', '9043927d-8a57-4e04-afb8-c6ae9918cfc2', true, 'Skitur! ⛷️', NULL),
