INSERT INTO "public"."packs" ("id", "created_at", "modified_at", "description", "name", "image", "language", "is_free") VALUES
	('ada05d82-599f-47dd-bf84-3fab425c3e37', '2024-08-03 11:07:00+00', '2024-12-05 23:15:12.814551+00', 'Lange dager, dårlig betalt og sure sjefer… Heldigvis varer det ikke for alltid, bare typ 60-70 år 💸', 'Workaholic', 'artworks/work.jpeg', 'nb', true),
	('117d2553-75bb-805b-afb5-e69737e4e1f5', '2024-10-06 16:57:00+00', '2024-12-05 23:15:13.061011+00', 'Logg av ansvar og sleng på lederhosen! Nå er det tid for pils!', 'Oktoberfest', 'artworks/octoberfest.jpeg', 'nb', false),
	('37904104-976a-410a-abd7-d47cf4383113', '2024-08-02 14:54:00+00', '2024-12-05 23:15:12.278618+00', 'Meet new people with smooth introductions and memorable chats! Perfect for breaking the ice and getting to know new people.', 'Meet and Greet', 'artworks/meet_n_greet.jpeg', 'sfw', true),
	('9876f988-790e-4b5f-b7d9-8acd75dcf434', '2024-08-02 12:46:00+00', '2024-12-05 23:15:12.290584+00', 'Get to know new people with smooth introductions and memorable chats! Perfect for breaking the ice and getting to know new people.', 'Meet and Greet', 'artworks/meet_n_greet.jpeg', 'en', true),
	('10fd2553-75bb-8063-9fc6-f128c7dea70d', '2024-09-28 11:58:00+00', '2024-12-05 23:15:12.296587+00', NULL, 'Köttbullar', 'artworks/festival.jpeg', 'sv', true),
	('10ed2553-75bb-80c3-8648-e3c1f44804fa', '2024-09-27 16:32:00+00', '2024-12-05 23:15:12.302374+00', 'Enjoy a pack full of challenging exams, grades and even student loans.', 'Back to School', 'artworks/student.jpeg', 'sfw', false),
	('bc0d7154-1fff-45be-8897-d4111953a547', '2024-07-20 09:56:00+00', '2024-12-05 23:15:12.326162+00', 'Sus gjennom drinken i høyeste gir! Hvem kommer først i mål? (Målet er doskåla)', 'Formel 1', 'artworks/formula1.jpeg', 'nb', true),
	('453b9a6e-aeb6-46dc-b9ec-bc0625105399', '2023-04-12 23:20:00+00', '2024-12-05 23:15:12.357549+00', 'Dårlig råd, rævva karakterer, maktsjuke forelesere, hva mer kan man ønske seg?', 'Studenten', 'artworks/student.jpeg', 'nb', true),
	('11ed2553-75bb-803e-804a-fd2477094413', '2024-10-13 20:03:00+00', '2024-12-05 23:15:12.357992+00', 'Frampek: Du blir dritings og spyr på de nye fine klærne dine og blir kastet ut fra julebordet før klokka er 20.', 'Julebordet', 'artworks/santa.jpeg', 'nb', true);
